	'messages:apihelp-query+search-paramvalue-prop-isfilematch' => 'fr:Ajoute un booléen indiquant si la recherche correspond au contenu du fichier.',
	'messages:apihelp-query+search-paramvalue-prop-extensiondata' => 'fr:Va ajouter des données générées supplémentaires par extension.',
	'messages:apihelp-query+search-paramvalue-prop-score' => 'fr:Ignoré.',
	'messages:apihelp-query+search-paramvalue-prop-hasrelated' => 'fr:Ignoré.',
	'messages:apihelp-query+search-param-limit' => 'fr:Combien de pages renvoyer au total.',
	'messages:apihelp-query+search-param-interwiki' => 'fr:Inclure les résultats interwiki dans la recherche, s’ils sont disponibles.',
	'messages:apihelp-query+search-param-backend' => 'fr:Quel serveur de recherche utiliser, si ce n’est pas celui par défaut.',
